#include <iostream>
#include <vector>
#include <algorithm>
void mergeSort(std::vector<int>& a,std::vector<int>& tmp,std::size_t lo,std::size_t hi){if(hi-lo<2)return;auto mid=lo+(hi-lo)/2;mergeSort(a,tmp,lo,mid);mergeSort(a,tmp,mid,hi);auto i=lo,j=mid,k=lo;while(i<mid&&j<hi)tmp[k++]=a[i]<=a[j]?a[i++]:a[j++];while(i<mid)tmp[k++]=a[i++];while(j<hi)tmp[k++]=a[j++];for(k=lo;k<hi;++k)a[k]=tmp[k];}
int main(){int n;if(!(std::cin>>n)||n<0||n>10000)return 0;std::vector<int>a(n);for(int&x:a)if(!(std::cin>>x))return 0;std::vector<int>tmp(a.size());mergeSort(a,tmp,0,a.size());for(std::size_t i=0;i<a.size();++i)std::cout<<(i?" ":"")<<a[i];std::cout<<"\n";}
